package com.example.rokidgeminisecretary;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;
/** Small local checks only. Never captures, sends, replays or repairs user data. */
final class LocalHealthCheck {
 static final java.util.concurrent.atomic.AtomicBoolean running=new java.util.concurrent.atomic.AtomicBoolean();static volatile JSONObject latest;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("local_health",0);}
 static long version(Context c){try{return c.getPackageManager().getPackageInfo(c.getPackageName(),0).getLongVersionCode();}catch(Exception e){return -1;}}
 static JSONObject snapshot(Context c){try{JSONObject value=new JSONObject(prefs(c).getString("result","{}"));if(latest!=null&&latest.optLong("at")>=value.optLong("at"))value=new JSONObject(latest.toString());value.put("running",running.get()).put("currentVersion",version(c));return value;}catch(Exception e){return new JSONObject();}}
 static void start(Context value,boolean force){Context c=value.getApplicationContext();if(!force&&snapshot(c).optLong("version",-2)==version(c))return;if(!running.compareAndSet(false,true))return;new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);try{JSONObject result=run(c);latest=result;prefs(c).edit().putString("result",result.toString()).commit();}catch(Exception e){try{latest=new JSONObject().put("version",version(c)).put("at",System.currentTimeMillis()).put("overall","failed");prefs(c).edit().putString("result",latest.toString()).commit();}catch(Exception ignored){}}finally{running.set(false);}},"LocalHealthCheck").start();}
 static final class NotReady extends Exception{}
 interface Check{void run()throws Exception;}
 static void check(JSONArray checks,String id,Check test)throws Exception{try{test.run();checks.put(new JSONObject().put("id",id).put("state","passed"));}catch(Exception e){checks.put(new JSONObject().put("id",id).put("state",e instanceof NotReady?"warning":"failed"));}}
 static JSONObject run(Context c)throws Exception{JSONArray checks=new JSONArray();check(checks,"storage",()->{if(c.getFilesDir().getUsableSpace()<50000000)throw new IOException();File probe=File.createTempFile("loki-health-",".probe",c.getCacheDir());AtomicFile f=new AtomicFile(probe);FileOutputStream out=null;byte[] bytes="loki-local-health-v1".getBytes("UTF-8");try{out=f.startWrite();out.write(bytes);out.getFD().sync();f.finishWrite(out);out=null;if(!java.util.Arrays.equals(bytes,f.readFully()))throw new IOException();}finally{if(out!=null)f.failWrite(out);f.delete();}});
 check(checks,"vault",()->{byte[] input="loki-local-health-v1".getBytes("UTF-8");java.security.KeyStore store=java.security.KeyStore.getInstance("AndroidKeyStore");store.load(null);if(!store.containsAlias("loki-photo-vault-v1"))throw new NotReady();java.security.Key key=store.getKey("loki-photo-vault-v1",null);if(!(key instanceof javax.crypto.SecretKey))throw new IOException();PhotoVaultCipher cipher=new PhotoVaultCipher((javax.crypto.SecretKey)key);if(!java.util.Arrays.equals(input,cipher.decrypt(cipher.encrypt(input))))throw new IOException();});
 boolean phone=c.getPackageName().equals("com.example.rokidgeminisecretary");check(checks,"assets",()->{if(phone){for(String name:new String[]{"index.html","app.js","media-attachments.js","local-records.js","reliability.js","style.css","icon.png"})try(InputStream in=c.getAssets().open("loki-web/"+name)){if(in.read()<0)throw new IOException();}}else{String sample="";for(String name:c.getAssets().list(""))if(name.endsWith(".png")){sample=name;break;}if(sample.isEmpty())throw new IOException();android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;try(InputStream in=c.getAssets().open(sample)){android.graphics.BitmapFactory.decodeStream(in,null,options);}if(options.outWidth<=0||options.outHeight<=0)throw new IOException();}});
 if(phone)check(checks,"queue",()->{new JSONArray(c.getSharedPreferences("phone_secretary",0).getString("pending_command_queue","[]"));new JSONArray(c.getSharedPreferences("loki_web_console",0).getString("outbox","[]"));});
 java.util.Set<String> declared=new java.util.HashSet<>();String[] requested=c.getPackageManager().getPackageInfo(c.getPackageName(),android.content.pm.PackageManager.GET_PERMISSIONS).requestedPermissions;if(requested!=null)java.util.Collections.addAll(declared,requested);
 for(String[] permission:new String[][]{{"microphone","android.permission.RECORD_AUDIO"},{"camera","android.permission.CAMERA"}})checks.put(new JSONObject().put("id",permission[0]).put("state",!declared.contains(permission[1])?"not_required":c.checkSelfPermission(permission[1])==0?"passed":"warning"));
 String overall="passed";for(int i=0;i<checks.length();i++){String state=checks.getJSONObject(i).getString("state");if(state.equals("failed"))overall="failed";else if(state.equals("warning")&&!overall.equals("failed"))overall="warning";}
 return new JSONObject().put("version",version(c)).put("at",System.currentTimeMillis()).put("overall",overall).put("checks",checks);}
 static JSONObject publicSummary(JSONObject input)throws Exception{JSONObject safe=new JSONObject().put("version",input.optLong("version",-1)).put("currentVersion",input.optLong("currentVersion",-1)).put("at",Math.max(0,input.optLong("at"))).put("running",input.optBoolean("running"));String overall=input.optString("overall");safe.put("overall",overall.matches("passed|failed|warning")?overall:"unknown");JSONArray rows=new JSONArray(),source=input.optJSONArray("checks");if(source!=null)for(int i=0;i<Math.min(8,source.length());i++){JSONObject row=source.getJSONObject(i);String id=row.optString("id"),state=row.optString("state");if(id.matches("storage|vault|assets|queue|microphone|camera")&&state.matches("passed|failed|warning|not_required"))rows.put(new JSONObject().put("id",id).put("state",state));}return safe.put("checks",rows);}
 static String describe(JSONObject j){String state=j.optString("overall"),label=state.equals("passed")?"合格":state.equals("warning")?"許可などの確認が必要":state.equals("failed")?"確認が必要":"未確認";StringBuilder text=new StringBuilder("ローカル動作チェック："+label+(j.optBoolean("running")?"（再検査中）":""));if(j.optLong("version",-1)!=j.optLong("currentVersion",-1))text.append("・別バージョンの結果");JSONArray checks=j.optJSONArray("checks");if(checks!=null)for(int i=0;i<checks.length();i++){JSONObject row=checks.optJSONObject(i);String id=row.optString("id"),name=id.equals("storage")?"保存領域":id.equals("vault")?"暗号化保存の往復":id.equals("assets")?"同梱ファイル（画像は代表1点）":id.equals("queue")?"依頼記録の形式":id.equals("microphone")?"マイク許可":"カメラ許可";text.append("\n").append(name).append("：").append(row.optString("state").equals("not_required")?"対象外（このアプリは要求しません）":row.optString("state").equals("passed")?"確認済み":row.optString("state").equals("warning")?(id.equals("microphone")||id.equals("camera")?"未許可":"未準備"):"要確認");}return text.append("\n通信・会話・実録音の成功を保証する検査ではありません。保存データの修復・依頼の再送はしません。").toString();}
 private LocalHealthCheck(){}
}
